CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role = 'admin'));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.qualifi_is_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles r JOIN auth.users u ON u.id=r.user_id WHERE r.user_id=auth.uid() AND r.role='admin' AND u.email_confirmed_at IS NOT NULL AND u.raw_app_meta_data->'qualifi_admin'='true'::jsonb) $$;
REVOKE ALL ON FUNCTION public.qualifi_is_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.qualifi_is_admin() TO authenticated;
CREATE TABLE public.qualifi_leads (id uuid PRIMARY KEY, email text NOT NULL, company text, kind text NOT NULL CHECK (kind IN ('waitlist','pilot','meeting')), page_id text NOT NULL, campaign_id text, locale text NOT NULL CHECK (locale IN ('tr','en')), segment text NOT NULL, solution text NOT NULL, utm_source text, utm_medium text, utm_campaign text, utm_content text, contact_status text NOT NULL DEFAULT 'new' CHECK (contact_status IN ('new','contacted','demo_scheduled','not_a_fit')), analytics_consent boolean NOT NULL DEFAULT false, visitor_id uuid, file_mode text NOT NULL DEFAULT 'sample' CHECK(file_mode='sample'), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(email,page_id,kind), CHECK(analytics_consent OR visitor_id IS NULL));
GRANT SELECT (id,email,company,kind,page_id,campaign_id,locale,solution,utm_source,utm_medium,utm_campaign,utm_content,contact_status,created_at) ON public.qualifi_leads TO authenticated;
GRANT UPDATE(contact_status) ON public.qualifi_leads TO authenticated;
GRANT ALL ON public.qualifi_leads TO service_role;
ALTER TABLE public.qualifi_leads ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_read ON public.qualifi_leads FOR SELECT TO authenticated USING(public.qualifi_is_admin());
CREATE POLICY admin_status ON public.qualifi_leads FOR UPDATE TO authenticated USING(public.qualifi_is_admin()) WITH CHECK(public.qualifi_is_admin());
CREATE TABLE public.qualifi_events (id uuid PRIMARY KEY, event text NOT NULL CHECK(event IN ('landing_viewed','primary_cta_clicked','lead_form_started','contract_selected','calendar_opened','solution_viewed','solution_selected','outcome_selected','agent_cta_clicked','lead_form_opened','agent_setup_started','channel_preference_selected','waitlist_joined','pilot_request_created','meeting_request_created')), page_id text NOT NULL, locale text NOT NULL CHECK(locale IN ('tr','en')), visitor_id uuid NOT NULL, properties jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.qualifi_events TO authenticated;
GRANT ALL ON public.qualifi_events TO service_role;
ALTER TABLE public.qualifi_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_events ON public.qualifi_events FOR SELECT TO authenticated USING(public.qualifi_is_admin());
CREATE TABLE public.qualifi_request_outcomes (lead_id uuid PRIMARY KEY REFERENCES public.qualifi_leads(id) ON DELETE CASCADE, event text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.qualifi_request_outcomes TO service_role;
ALTER TABLE public.qualifi_request_outcomes ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.qualifi_save_lead(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE saved uuid; previous public.qualifi_leads; outcome text; BEGIN
SELECT * INTO previous FROM public.qualifi_leads WHERE id=(p->>'id')::uuid;
IF FOUND THEN IF previous.email=p->>'email' AND previous.page_id=p->>'page_id' AND previous.kind=p->>'kind' THEN RETURN jsonb_build_object('id',previous.id,'duplicate',true); ELSE RAISE EXCEPTION 'request_id_conflict'; END IF; END IF;
INSERT INTO public.qualifi_leads(id,email,company,kind,page_id,campaign_id,locale,segment,solution,utm_source,utm_medium,utm_campaign,utm_content,analytics_consent,visitor_id) VALUES ((p->>'id')::uuid,p->>'email',p->>'company',p->>'kind',p->>'page_id',p->>'campaign_id',p->>'locale',p->>'segment',p->>'solution',p->>'utm_source',p->>'utm_medium',p->>'utm_campaign',p->>'utm_content',(p->>'analytics_consent')::boolean,(p->>'visitor_id')::uuid) ON CONFLICT DO NOTHING RETURNING id INTO saved;
IF saved IS NULL THEN SELECT id INTO saved FROM public.qualifi_leads WHERE email=p->>'email' AND page_id=p->>'page_id' AND kind=p->>'kind'; IF saved IS NULL THEN RAISE EXCEPTION 'request_id_conflict'; END IF; RETURN jsonb_build_object('id',saved,'duplicate',true); END IF;
outcome := CASE p->>'kind' WHEN 'waitlist' THEN 'waitlist_joined' WHEN 'pilot' THEN 'pilot_request_created' ELSE 'meeting_request_created' END;
INSERT INTO public.qualifi_request_outcomes(lead_id,event) VALUES(saved,outcome);
IF (p->>'analytics_consent')::boolean THEN INSERT INTO public.qualifi_events(id,event,page_id,locale,visitor_id,properties) VALUES(saved,outcome,p->>'page_id',p->>'locale',(p->>'visitor_id')::uuid,jsonb_build_object('solution',p->>'solution')); END IF;
RETURN jsonb_build_object('id',saved,'duplicate',false); END $$;
REVOKE ALL ON FUNCTION public.qualifi_save_lead(jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.qualifi_save_lead(jsonb) TO service_role;
CREATE INDEX qualifi_leads_created ON public.qualifi_leads(created_at DESC,id DESC);
CREATE INDEX qualifi_events_scope ON public.qualifi_events(page_id,created_at,visitor_id);